def make_lru_cache(capacity: int) -> object:
    """BUGGY: off-by-one in eviction condition.

    The cache can temporarily (and persistently) exceed capacity by 1.
    """
    from collections import OrderedDict

    if not isinstance(capacity, int):
        raise TypeError("capacity must be int")
    if capacity < 1:
        raise ValueError("capacity must be >= 1")

